import {extraVisuals} from './education-visuals-extra.js';
// Original vector illustrations and explanatory interfaces. Artwork: CC BY 4.0.
// Clinical sources and graph definitions are also recorded in content/research/.
const source=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const svg=(id,title,description,body,box='0 0 960 500')=>`<svg class="education-svg" viewBox="${box}" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">${title}</title><desc id="${id}-desc">${description}</desc>${body}</svg>`;
const credit=references=>`<p class="education-credit">자체 제작 모식도 · ${source('https://creativecommons.org/licenses/by/4.0/','CC BY 4.0')} · 설명 근거: ${references}</p>`;

function drusenLayers(){
  const cells=Array.from({length:18},(_,i)=>{const x=185+i*31;const lift=45*Math.exp(-(((x-430)/70)**2));return `<g transform="translate(${x} ${170-lift})"><rect x="-7" y="0" width="14" height="74" rx="7" fill="${i%2?'#c4ac74':'#9eaa83'}" stroke="#657a61"/><ellipse cx="0" cy="18" rx="5" ry="8" fill="#52654f"/><path d="M-5-18v18M0-24V0M5-18V0" stroke="#b89d64" stroke-width="3"/></g>`;}).join('');
  return svg('drusen-layer','드루젠이 쌓이는 위치','시세포 아래의 망막색소상피와 브루크막 사이에 노란 드루젠이 쌓여 망막색소상피를 밀어 올립니다.',`<defs><linearGradient id="amd-vessel" x2="0" y2="1"><stop stop-color="#c78277"/><stop offset="1" stop-color="#914e4c"/></linearGradient></defs><rect width="960" height="500" rx="14" fill="#faf9f2"/><path d="M170 364H758L821 325H235Z" fill="#d5b3a7"/><path d="M170 364H758V413H170Z" fill="#c9998c"/><path d="m758 364 63-39v49l-63 39Z" fill="#b4857d"/><g fill="none" stroke="url(#amd-vessel)" stroke-width="16" stroke-linecap="round"><path d="M204 385c70-36 155 29 233-3s182 18 289-3"/><path d="m360 393 17-26m166 27 30-28m65 24 38-22"/></g><path d="M170 307H758L821 268H235Z" fill="#a8b9b5"/><path d="M170 307H758V316H170Z" fill="#6d8e88"/><path d="M170 269c90 0 133 0 170-1s45-52 90-52 54 51 102 52h226v22H532c-49 0-53-46-102-46s-49 45-90 45H170Z" fill="#8d7762" stroke="#6d5b4b" stroke-width="2"/><path d="M360 305c10-26 28-58 70-58s61 32 78 58Z" fill="#e6bd52" stroke="#bd943d" stroke-width="2"/>${cells}<g fill="#334f48" font-family="inherit" font-size="20"><text x="32" y="105" font-weight="700">빛을 받는 시세포</text><text x="32" y="260">망막색소상피</text><text x="32" y="321">브루크막</text><text x="32" y="402">맥락막 혈관</text><text x="585" y="468" font-weight="700" fill="#a47c1d">드루젠: 지방·단백질 침착물</text></g><g stroke="#799086" fill="none" stroke-width="2"><path d="M210 108h100l20 50"/><path d="M157 253h25"/><path d="M140 315h30"/><path d="M157 396h37"/><path d="M584 447H529l-78-149"/></g><circle cx="451" cy="298" r="5" fill="#b58d35"/>`);
}

function vascularDamage(){
  const panels=[{x:0,title:'1. 높은 혈당이 오래 지속',sub:'작은 혈관의 세포가 손상됩니다.',damage:false},{x:320,title:'2. 혈관벽 손상과 누출',sub:'혈관 벽이 약해져 물·피가 샙니다.',damage:true},{x:640,title:'3. 막힘과 비정상 새 혈관',sub:'산소 부족 → VEGF 증가',damage:true}];
  return svg('glucose-damage','만성 고혈당과 망막 미세혈관 손상','높은 혈당이 오래 지속되면 혈관벽과 이를 지지하는 세포가 손상됩니다. 누출은 부종과 출혈을, 혈관 막힘은 산소 부족과 비정상 신생혈관을 일으킬 수 있습니다.',panels.map((p,j)=>`<g transform="translate(${p.x} 0)"><rect x="8" y="10" width="304" height="410" rx="16" fill="${j?'#f9efe7':'#eef4ee'}"/><text x="27" y="50" font-size="18" font-weight="700" fill="#294f43">${p.title}</text><text x="27" y="79" font-size="14" fill="#61776c">${p.sub}</text><path d="M30 170H280V265H30" fill="#fcdfd8" stroke="#bd7466" stroke-width="4"/><g fill="#b2bd91" stroke="#819264">${[45,90,135,180,225].filter((_,i)=>!p.damage||i%2===0).map(x=>`<ellipse cx="${x}" cy="166" rx="18" ry="11"/><ellipse cx="${x+20}" cy="269" rx="18" ry="11"/>`).join('')}</g>${[58,109,160,211,261].map((x,i)=>`<ellipse cx="${x}" cy="${205+i%2*23}" rx="13" ry="7" fill="#b85d53"/>`).join('')}${[50,100,150,200,250].map(x=>`<path d="m${x} 111 8 5v9l-8 5-8-5v-9Z" fill="#e7bd63"/>`).join('')}${j===1?'<path d="M168 170q-14-47 25-41t14 41" fill="#efb6a7" stroke="#bd7466" stroke-width="4"/><path d="m140 260-20 44m77-43 29 42" stroke="#7caeaf" stroke-width="4"/><g fill="#7caeaf"><ellipse cx="117" cy="318" rx="9" ry="13"/><ellipse cx="230" cy="318" rx="9" ry="13"/></g><circle cx="203" cy="111" r="7" fill="#b85d53"/>':''}${j===2?'<path d="M162 172q40 42 0 90" stroke="#a98675" stroke-width="24" fill="none"/><g stroke="#bd6f69" stroke-width="3" fill="none"><path d="M228 170V133l-40-24m40 24 31-39m-22 31 35-5m-71-3-15-36"/><path d="m90 265 14 38-33 41m33-41 24 17"/></g>':''}<text x="27" y="367" font-size="15" fill="#5e7568">${j===0?'혈관의 지지 세포 · 내피세포':j===1?'미세혈관류 · 부종 · 출혈':'증식성 망막병증으로 이어질 수 있음'}</text></g>`).join('')+'<text x="30" y="465" font-size="16" fill="#6e7d72">이해를 위한 모식도입니다. 모든 변화가 같은 순서·속도로 나타나는 것은 아닙니다.</text>','0 0 960 490');
}

function axialLength(){
  return svg('axial-length','정시·근시·원시에서 눈 길이 비교','정시는 눈의 길이와 굴절력이 맞습니다. 안축성 근시는 눈이 긴 경우, 원시는 눈이 짧은 경우가 흔하지만 각막과 수정체 굴절력도 영향을 줍니다.',[{x:0,r:100,n:'정시',d:'길이와 굴절력이 맞는 눈'},{x:320,r:126,n:'근시',d:'눈의 길이가 긴 경우가 흔함'},{x:640,r:79,n:'원시',d:'눈의 길이가 짧은 경우가 흔함'}].map(p=>`<g transform="translate(${p.x} 0)"><rect x="5" y="10" width="310" height="290" rx="14" fill="#f0f4eb"/><text x="160" y="48" text-anchor="middle" font-size="22" font-weight="700" fill="#315e49">${p.n}</text><ellipse cx="153" cy="156" rx="${p.r}" ry="79" fill="#fffdf7" stroke="#839d89" stroke-width="3"/><path d="M${153-p.r+17} 117q-30 39 0 78" fill="#dbe9e7" stroke="#839d89" stroke-width="2"/><ellipse cx="${153-p.r+34}" cy="156" rx="12" ry="31" fill="#cad8b6"/><path d="M${153-p.r+17} 156H${153+p.r}" stroke="#b1bfaf" stroke-dasharray="5 5"/><path d="M${153-p.r+17} 249H${153+p.r}m-3-5 3 5-3 5m${-2*p.r+23}-10-3 5 3 5" stroke="#7e986e" fill="none" stroke-width="2"/><text x="160" y="282" text-anchor="middle" font-size="16" fill="#58745d">${p.d}</text></g>`).join('')+'<text x="30" y="338" font-size="16" fill="#6e7d72">안축성 굴절이상의 대표적 비교 · 실제 크기나 개인의 안축장 수치를 나타내지 않습니다.</text>','0 0 960 365');
}

const parkScene=`<rect width="440" height="270" fill="#dce9ec"/><circle cx="363" cy="49" r="22" fill="#f2d69c"/><path d="M0 171Q130 111 251 163t189-17v124H0Z" fill="#a1baa0"/><path d="M216 270q-23-67 15-115 40 39 78 115Z" fill="#eadbc0"/><path d="M77 174v-81m-12 81h24" stroke="#8b8271" stroke-width="11"/><circle cx="77" cy="91" r="41" fill="#789c80"/><path d="M356 188v-65" stroke="#8b8271" stroke-width="9"/><circle cx="356" cy="115" r="32" fill="#83a68a"/><g fill="#a27e63"><rect x="116" y="190" width="94" height="10" rx="2"/><rect x="121" y="171" width="85" height="10" rx="2"/><path d="M128 198v29h7v-29m55 0v29h7v-29"/></g><text x="20" y="250" font-size="20" fill="#335747">공원 산책길</text>`;
function amblyopiaView(){return `<div class="vision-comparison"><div><p class="visual-panel-label">선명하게 보는 눈의 예</p>${svg('amblyopia-clear','선명하게 보이는 공원','나무와 벤치, 글씨가 또렷한 자체 제작 장면입니다.',parkScene,'0 0 440 270')}</div><div><p class="visual-panel-label">약시가 있는 눈의 시야 예</p>${svg('amblyopia-blur','약시 시야의 선명도 저하 예','같은 공원 장면을 흐리게 표현했습니다. 약시의 모습은 사람마다 다릅니다. 단순히 안경 도수가 안 맞아서 흐린 경우와 구분해야 합니다.','<defs><filter id="amblyopia-blur-filter"><feGaussianBlur stdDeviation="3.3"/></filter></defs><g filter="url(#amblyopia-blur-filter)">'+parkScene+'</g>','0 0 440 270')}</div></div><p class="visual-note">시력 발달의 차이로 안경을 맞춘 뒤에도 선명도가 낮을 수 있음을 표현했습니다. 실제 시력 수치를 재현한 그림은 아니며 약시의 모습은 다양합니다.</p>`;}

function eyelidTriggers(){const cards=[['☾','수면 부족·피로','수면 시간을 확보해 보세요.'],['≈','스트레스','긴장을 풀고 휴식하세요.'],['☕','과도한 카페인','커피·에너지 음료를 줄여보세요.'],['◉','눈 건조·자극','눈 표면을 편안하게 관리하세요.']];return `<div class="trigger-grid">${cards.map(([icon,title,text])=>`<div class="trigger-card"><span aria-hidden="true">${icon}</span><strong>${title}</strong><p>${text}</p></div>`).join('')}</div><p class="visual-note">흔한 눈꺼풀 근육 떨림을 유발하거나 악화시킬 수 있는 요인입니다. 눈이 세게 감기거나 얼굴 다른 부위로 퍼지는 경련은 진료로 구분합니다.</p>`;}

function vitreous(){return `<div class="vitreous-model" id="vitreous-model" data-vitreous-model><p class="visual-panel-label">유리체 액화 · 입체 모형으로 살펴보기</p><canvas width="1000" height="510" role="img" aria-label="유리체 액화와 콜라겐 뭉침을 설명하는 회전 가능한 3D 개념 모형">젤리 같은 유리체에 액체 공간이 생기고, 남은 섬유가 뭉쳐 그림자를 만듭니다.</canvas><div class="model-controls"><label for="vitreous-progress">액화 설명 단계 <output id="vitreous-stage">초기</output><input id="vitreous-progress" type="range" min="0" max="100" value="15" aria-describedby="vitreous-limit"></label><label for="vitreous-angle">3D 보기 각도<input id="vitreous-angle" type="range" min="-55" max="55" value="-15"></label><button class="secondary-button" type="button" data-vitreous-motion aria-pressed="false">부유물 움직임 보기</button><label class="haze-control"><input type="checkbox" data-vitreous-haze checked> 흐림 효과 함께 보기</label></div><p class="model-explanation" data-vitreous-description aria-live="polite">젤 구조 사이에 작은 액체 공간이 생기는 단계를 표현했습니다.</p><p class="visual-note" id="vitreous-limit">단계는 나이·액화 비율·개인의 진행 속도를 나타내지 않습니다. 흐림 효과는 부유물의 그림자와 산란을 강조한 표현입니다. <strong>유리체 액화가 늘수록 전체 시야가 일정하게 흐려지는 것은 아닙니다.</strong> 갑작스러운 뿌연 시야·점의 급증·번쩍임·커튼 같은 가림은 출혈·염증·망막열공 등을 확인해야 합니다.</p></div>`;}

function injectionDiagram(){return svg('intravitreal-route','안구내 주사: 유리체에 약을 전달하는 경로','주사 바늘이 눈의 흰자를 통해 유리체 공간에 들어가 약을 전달하는 개념 모식도. 수정체나 망막에 직접 주사하는 것이 아닙니다.',`<rect width="960" height="520" rx="14" fill="#f2f5ed"/><path d="m751 248 65 13v56l-65 13" fill="#d3bd95"/><ellipse cx="485" cy="279" rx="265" ry="190" fill="#fffdf6" stroke="#8da38d" stroke-width="5"/><path d="M385 108a254 178 0 1 1 0 342" fill="#e6efdf" stroke="#c69b85" stroke-width="7"/><path d="M239 191q-67 89 0 177 16-86 0-177Z" fill="#d7e9e9" stroke="#8ca7a2" stroke-width="3"/><ellipse cx="290" cy="279" rx="27" ry="65" fill="#c1d3ad" stroke="#8da47d" stroke-width="2"/><path d="M263 193v48m0 76v48" stroke="#829970" stroke-width="12"/><g transform="translate(160 30) rotate(36)"><path d="M20-12h28v24H20Z" fill="#c0cece" stroke="#6b8d8d" stroke-width="2"/><path d="M48-23h120v46H48Z" fill="#e1edef" stroke="#6b8d8d" stroke-width="3"/><path d="M53-17h55v34H53Z" fill="#9bbfc3"/><path d="M68-23v10m24-10v10m24-10v10m24-10v10" stroke="#6b8d8d" stroke-width="2"/><path d="M168-10h17v20h-17Z" fill="#a5c5c5"/><path d="M185 0h91" stroke="#7c8d89" stroke-width="3"/><path d="M20-22v44" stroke="#6b8d8d" stroke-width="7"/></g><g fill="#7aafb5"><circle cx="406" cy="218" r="7"/><circle cx="427" cy="232" r="5"/><circle cx="446" cy="211" r="4"/><circle cx="428" cy="199" r="3"/></g><g fill="#36594c" font-family="inherit"><text x="79" y="125" font-size="20">가는 주사 바늘</text><text x="467" y="286" font-size="27" font-weight="700">유리체</text><text x="463" y="319" font-size="18">약이 전달되는 공간</text><text x="268" y="399" font-size="18">수정체</text><text x="775" y="197" font-size="18">망막</text><text x="447" y="72" font-size="20">흰자를 통해 눈 안으로</text></g><g stroke="#839b90" fill="none" stroke-width="2"><path d="M470 81H398l-71 85"/><path d="M285 380v-35"/><path d="M801 203l-84 20"/></g>`)+`<p class="visual-note">치료 원리를 설명하는 모식도입니다. 실제 바늘·안구의 크기와 각도는 단순화했습니다. 시술은 소독과 마취 후 의료진이 시행합니다.</p>`;}

const visuals={
  'drusen-layers':()=>drusenLayers()+credit(source('https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/age-related-macular-degeneration','NEI · 황반변성')),
  'glucose-vessels':()=>vascularDamage()+credit(source('https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/diabetic-retinopathy','NEI · 당뇨망막병증')),
  'axial-length':()=>axialLength()+credit(source('https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/refractive-errors','NEI · 굴절이상')),
  'amblyopia-view':()=>amblyopiaView()+credit(source('https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/amblyopia-lazy-eye','NEI · 약시')),
  'eyelid-triggers':()=>eyelidTriggers()+credit(source('https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/blepharospasm','NEI · 눈꺼풀 떨림')),
  'vitreous-model':()=>vitreous()+credit(source('https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/floaters','NEI · 비문증'))
  ,'intravitreal-route':()=>injectionDiagram()+credit(source('https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/diabetic-retinopathy/injections-treat-eye-conditions','NEI · 안구내 주사'))
  ,...extraVisuals
};
export const hasEducationalVisual=id=>Object.hasOwn(visuals,id);
export const educationalVisualHTML=id=>id&&hasEducationalVisual(id)?`<div class="education-figure" data-education-visual="${id}">${visuals[id]()}</div>`:'';
export function insertSectionVisuals(html,topicId){
  if(topicId!=='floaters-pvd')return html;
  return html.replace('<p><strong>① 노화에 의한 비문증 (유리체 액화·후유리체박리)</strong></p>',match=>match+educationalVisualHTML('vitreous-model'));
}

export function setupPdtInfo(){
  const dialog=document.createElement('dialog');dialog.id='pdt-info-dialog';dialog.className='clinical-info-dialog';dialog.setAttribute('aria-labelledby','pdt-info-title');
  dialog.innerHTML='<div class="dialog-head"><h2 id="pdt-info-title">광역학치료(PDT) 시행 문의</h2><button type="button" class="icon-button" aria-label="PDT 안내 닫기" autofocus>×</button></div><p>PDT는 국내에서 시행하는 병원이 한정되어 있어, 필요하면 시행 가능한 병원에 문의하세요.</p><p><strong>문의할 병원 예시</strong><br>서울아산병원 · 삼성서울병원 · 서울대학교병원 · 김안과병원 · 누네안과병원 등</p><p class="visual-note">진료과·의료진·약제 공급 상황에 따라 시행 여부가 달라질 수 있습니다. 방문 전에 현재 시행 여부와 예약·의뢰 절차를 확인하세요.</p>';
  document.body.append(dialog);dialog.querySelector('button').addEventListener('click',()=>dialog.close());
  document.addEventListener('click',event=>{if(event.target.closest('[data-pdt-info]')){event.preventDefault();dialog.showModal();}});
  window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();});
}
